(function(){"use strict";const PUBLIC_ICAL_URL="https://calendar.google.com/calendar/ical/harshsaw01%40gmail.com/public/basic.ics";const CACHE_STORAGE_KEY="mbbs_timetable_cache_v2";const SETTINGS_STORAGE_KEY="mbbs_timetable_settings_v2";const REFRESH_INTERVAL_MS=15*60*1000;const DEFAULT_EXCLUDE_KEYWORDS=["birthday","anniversary","marriage","sleep","routine","dinner","reading","exercise","water plants","journaling","brush","freshen up","meditation","meditate","planning","eat something","study session","power hour","revise","revision","canva","times prime","vehicle registration","shopping","groceries","haircut","workout","gym","make bed","listen articles","drop school","growth 365","study psychology","study time","demon slayer","spider","animal (a)","animal","stree 2","shaitan","movie","netflix","youtube","cinema","crowdsource","aptitude test","contrarian investing","harsh और","coaching","🧑🏻‍🏫 coaching","botany |","chemistry |","physics |","zoology |","aiats","cst","nbts","pst","fts","ft-","project phoenix","pre-neet","pre neet","test darwin","test :","test-","mock","neet form","bus trip","train trip","flight"];const DEFAULT_COLLEGE_SUBJECTS=["anatomy","physiology","biochemistry","aetcom","ece","psm","community medicine","forensic","pathology","pharmacology","microbiology","sports & eca","college"];const state={activeView:"today",selectedSubject:"all",selectedSessionType:"all",searchQuery:"",allCollegeSessions:[],lastSyncTime:null,isSynced:false,isLoading:false,errorMessage:null,manualExcludedUids:new Set(),customIncludeWords:[],customExcludeWords:[],strictCollegeFilter:true};let DOM={};function initDOM(){DOM={currentTimeBadge:document.getElementById("current-time-badge"),lastSyncedText:document.getElementById("last-synced-text"),syncUpToDateBadge:document.getElementById("sync-uptodate-badge"),floatingTodayBtn:document.getElementById("btn-floating-today"),filterPillsScroll:document.querySelector(".filter-pills-scroll"),filterPillsContainer:document.querySelector(".filter-pills-container"),refreshBtn:document.getElementById("btn-refresh-timetable"),filterSettingsBtn:document.getElementById("btn-filter-settings"),viewTabs:document.querySelectorAll(".timetable-nav-tabs .tab-btn"),tabTodayCount:document.getElementById("tab-count-today"),tabUpcomingCount:document.getElementById("tab-count-upcoming"),subjectPills:document.querySelectorAll(".filter-pills-scroll .sub-pill"),typeSelect:document.getElementById("session-type-select"),searchInput:document.getElementById("timetable-search-input"),searchClear:document.getElementById("timetable-search-clear"),timelineContainer:document.getElementById("timetable-timeline-container"),nowBannerContainer:document.getElementById("now-banner-container"),loadingState:document.getElementById("timetable-loading-state"),emptyState:document.getElementById("timetable-empty-state"),errorState:document.getElementById("timetable-error-state"),errorDetailsText:document.getElementById("error-details-text"),retryBtn:document.getElementById("btn-retry-fetch"),detailsModal:document.getElementById("session-details-modal"),detailsCloseBtn:document.getElementById("session-details-close"),detailsTitle:document.getElementById("modal-session-title"),detailsTime:document.getElementById("modal-session-time"),detailsSubjectBadge:document.getElementById("modal-subject-badge"),detailsTypeBadge:document.getElementById("modal-type-badge"),detailsFaculty:document.getElementById("modal-session-faculty"),detailsCompetency:document.getElementById("modal-session-competency"),detailsLocation:document.getElementById("modal-session-location"),detailsDescription:document.getElementById("modal-session-description"),detailsExportIcsBtn:document.getElementById("modal-export-ics-btn"),settingsModal:document.getElementById("timetable-settings-modal"),settingsCloseBtn:document.getElementById("settings-modal-close"),strictFilterToggle:document.getElementById("toggle-strict-filter"),customIncludeInput:document.getElementById("settings-custom-include"),customExcludeInput:document.getElementById("settings-custom-exclude"),settingsSaveBtn:document.getElementById("btn-save-settings"),settingsResetBtn:document.getElementById("btn-reset-settings")};}
function getNowInKolkata(){const now=new Date();const utcTime=now.getTime()+(now.getTimezoneOffset()*60000);const kolkataOffsetMs=5.5*3600000;return new Date(utcTime+kolkataOffsetMs);}
function formatTimeAMPM(dateObj){let hours=dateObj.getHours();let minutes=dateObj.getMinutes();const ampm=hours>=12?"PM":"AM";hours=hours%12;hours=hours?hours:12;const strMinutes=minutes<10?"0"+minutes:minutes;const strHours=hours<10?"0"+hours:hours;return`${strHours}:${strMinutes} ${ampm}`;}
function formatDateHuman(dateObj){const days=["Sunday","Monday","Tuesday","Wednesday","Thursday","Friday","Saturday"];const months=["Jan","Feb","Mar","Apr","May","Jun","Jul","Aug","Sep","Oct","Nov","Dec"];return`${days[dateObj.getDay()]}, ${dateObj.getDate()} ${months[dateObj.getMonth()]} ${dateObj.getFullYear()}`;}
function formatRelativeDay(targetDate,todayDate){const targetMid=new Date(targetDate.getFullYear(),targetDate.getMonth(),targetDate.getDate());const todayMid=new Date(todayDate.getFullYear(),todayDate.getMonth(),todayDate.getDate());const diffDays=Math.round((targetMid-todayMid)/(1000*60*60*24));if(diffDays===0)return"Today";if(diffDays===1)return"Tomorrow";if(diffDays===-1)return"Yesterday";if(diffDays>1&&diffDays<=6)return`In ${diffDays} days`;return"";}
function parseIcsDate(dtStr){if(!dtStr)return null;const isUtc=dtStr.endsWith("Z");const clean=dtStr.replace("Z","");let year,month,day,hour=0,minute=0,second=0;if(clean.includes("T")){const parts=clean.split("T");year=parseInt(parts[0].substr(0,4),10);month=parseInt(parts[0].substr(4,2),10)-1;day=parseInt(parts[0].substr(6,2),10);hour=parseInt(parts[1].substr(0,2),10);minute=parseInt(parts[1].substr(2,2),10);second=parseInt(parts[1].substr(4,2),10);}else{year=parseInt(clean.substr(0,4),10);month=parseInt(clean.substr(4,2),10)-1;day=parseInt(clean.substr(6,2),10);}
if(isUtc){const d=new Date(Date.UTC(year,month,day,hour,minute,second));d.setUTCMinutes(d.getUTCMinutes()+330);return new Date(d.getUTCFullYear(),d.getUTCMonth(),d.getUTCDate(),d.getUTCHours(),d.getUTCMinutes(),d.getUTCSeconds());}else{return new Date(year,month,day,hour,minute,second);}}
function isCollegeEvent(summary,desc,loc,startDt,endDt){if(!summary)return false;const sLow=summary.toLowerCase().trim();const dLow=(desc||"").toLowerCase();const lLow=(loc||"").toLowerCase();const fullText=`${sLow} ${dLow} ${lLow}`;for(const inc of state.customIncludeWords){if(inc&&sLow.includes(inc))return true;}
for(const exc of state.customExcludeWords){if(exc&&sLow.includes(exc))return false;}
if(state.strictCollegeFilter){for(const exc of DEFAULT_EXCLUDE_KEYWORDS){if(sLow.includes(exc))return false;}
if(summary==="🏫 College"||summary==="College"){if(startDt&&endDt){const durationHrs=(endDt.getTime()-startDt.getTime())/(1000*60*60);if(durationHrs>=6||(startDt.getHours()<=9&&endDt.getHours()>=17)){return false;}}else if(sLow==="college"){return false;}}
const collegeKeywords=["anatomy","physiology","biochemistry","pathology","pharmacology","microbiology","community medicine","psm","forensic","aetcom","ece","sports & eca","sports","holiday","medical college","dissection","doap","sgt","histology","sdl","recess","lunch"];for(const subj of collegeKeywords){if(fullText.includes(subj))return true;}
if(startDt){const day=startDt.getDay();if(day>=1&&day<=6){const hr=startDt.getHours();if(hr>=8&&hr<17){return true;}}}
return false;}
return true;}
function detectSubject(summary,desc,loc){const titleLow=(summary||"").toLowerCase().trim();const fullText=`${summary || ""} ${desc || ""} ${loc || ""}`.toLowerCase();if(titleLow.includes("lunch")||titleLow.includes("break")||titleLow.includes("recess")){return"break";}
if(titleLow.includes("holiday")||titleLow.includes("vacation")||titleLow.includes("dussehra")||titleLow.includes("diwali")){return"holiday";}
if(titleLow.includes("biochemistry")||/\bbc\s*\d/i.test(titleLow)){return"biochemistry";}
if(titleLow.includes("physiology")||/\bpy\s*\d/i.test(titleLow)){return"physiology";}
if(titleLow.includes("anatomy")||titleLow.includes("dissection")||titleLow.includes("histology")||/\ban\s*\d/i.test(titleLow)){return"anatomy";}
if(titleLow.includes("aetcom")){return"aetcom";}
if(titleLow.includes("ece")){return"ece";}
if(titleLow.includes("sports")||titleLow.includes("eca")){return"sports";}
if(titleLow.includes("pathology")){return"pathology";}
if(titleLow.includes("pharmacology")){return"pharmacology";}
if(titleLow.includes("microbiology")){return"microbiology";}
if(titleLow.includes("community medicine")||titleLow.includes("psm")){return"community";}
if(titleLow.includes("forensic")||titleLow.includes("fmt")){return"forensic";}
if(/clinic|posting|ward|surgery|pediatrics|medicine|obg|ophthalmology|ent|orthopedics/i.test(titleLow)){return"clinical";}
if(/\b(biochemistry|urine sample|lipid|protein|carbohydrate|vitamins)\b/i.test(fullText)){return"biochemistry";}
if(/\b(physiology|ecg|git disorders|salivary|pancreas|colon)\b/i.test(fullText)){return"physiology";}
if(/\b(anatomy|dissection|histology|pericardium|sternum|mediastinum|heart|lungs|atrium)\b/i.test(fullText)){return"anatomy";}
return"general";}
function detectSessionType(summary,desc){const s=`${summary} ${desc}`.toLowerCase();if(s.includes("(l)")||s.includes("lecture")||s.includes("(l):")||s.includes("l:")){return"lecture";}
if(s.includes("(dh)")||s.includes("dissection")){return"dissection";}
if(s.includes("practical")){return"practical";}
if(s.includes("(sgt)")||s.includes("doap")||s.includes("tutorial")){return"sgt_doap";}
if(s.includes("sdl")){return"sdl";}
if(s.includes("pct")||s.includes("class test")||s.includes("test")||s.includes("exam")){return"test_exam";}
if(s.includes("aetcom")){return"aetcom";}
if(s.includes("ece")){return"ece";}
if(s.includes("holiday")){return"holiday";}
if(s.includes("lunch")){return"break";}
return"other";}
function extractMetadata(title,desc,subject){let faculty="";let competency="";const cleanLines=[];const normalizedDesc=(desc||"").replace(/\\n/g,"\n").replace(/\\,/g,",").replace(/\\;/g,";");const lines=normalizedDesc.split("\n");for(const rawLine of lines){const line=rawLine.trim();const lower=line.toLowerCase();if(lower.startsWith("faculty:")||lower.includes("| faculty:")){const parts=line.split(/faculty:/i);faculty=parts[parts.length-1].trim();faculty=faculty.split(/department:|special class:|practical preparation:/i)[0].trim().replace(/^\(|\)$/g,"").trim();}else if(lower.startsWith("competency:")){competency=line.substring(11).trim();}else{cleanLines.push(line);}}
if(!competency&&title){const compMatch=title.match(/\b(AN|BC|PY)\s*\d+(\.\d+)?(-\d+(\.\d+)?)?\b/i);if(compMatch){competency=compMatch[0].toUpperCase();}}
if(!faculty&&title){const initialsMap={BNK:"Dr. Bakhshilal Kumar (BNK)",HBS:"Dr. Hemlata B. Sheik (HBS)",SD:"Dr. Shreya Dhurandher (SD)",R:"Dr. Ritika (R)",AR:"Dr. Anantika Rai (AR)",FKK:"Dr. Firoj Kumar Khare (FKK)",FK:"Dr. Firoj Kumar Khare (FK)"};for(const[init,name]of Object.entries(initialsMap)){if(new RegExp(`\\b${init}\\b`).test(title)){faculty=name;break;}}}
if(!faculty){if(subject==="anatomy")faculty="Anatomy Faculty";else if(subject==="physiology")faculty="Physiology Faculty";else if(subject==="biochemistry")faculty="Biochemistry Faculty";else if(subject==="aetcom")faculty="AETCOM Faculty";else if(subject==="ece")faculty="ECE Faculty";else if(subject==="break")faculty="Lunch Break";else if(subject==="holiday")faculty="College Holiday";else faculty="Department Faculty";}
return{faculty,competency,cleanDesc:cleanLines.filter(Boolean).join("\n")};}
function parseIcalString(rawIcs){const unfolded=rawIcs.replace(/\r?\n[ \t]/g,"");const rawEvents=unfolded.split("BEGIN:VEVENT");const baseRecurring=[];const overrides={};const exdates={};const standalone=[];for(let i=1;i<rawEvents.length;i++){const ev=rawEvents[i];const uidMatch=ev.match(/UID:(.*)/);const sumMatch=ev.match(/SUMMARY:(.*)/);const startMatch=ev.match(/DTSTART(?:;[^:]+)?:([0-9TZ]+)/);if(!uidMatch||!sumMatch||!startMatch)continue;const uid=uidMatch[1].trim();const summary=sumMatch[1].replace(/\\,/g,",").replace(/\\;/g,";").trim();const descMatch=ev.match(/DESCRIPTION:(.*)/);const desc=descMatch?descMatch[1].replace(/\\n/g,"\n").replace(/\\,/g,",").trim():"";const locMatch=ev.match(/LOCATION:(.*)/);const loc=locMatch?locMatch[1].replace(/\\,/g,",").trim():"";const statusMatch=ev.match(/STATUS:(.*)/);const status=statusMatch?statusMatch[1].trim():"CONFIRMED";if(status.toUpperCase()==="CANCELLED")continue;if(state.manualExcludedUids.has(uid))continue;const startDt=parseIcsDate(startMatch[1].trim());if(!startDt)continue;const endMatch=ev.match(/DTEND(?:;[^:]+)?:([0-9TZ]+)/);let endDt=endMatch?parseIcsDate(endMatch[1].trim()):new Date(startDt.getTime()+60*60*1000);if(!isCollegeEvent(summary,desc,loc,startDt,endDt))continue;const exRegex=/EXDATE(?:;[^:]+)?:([0-9TZ,]+)/g;let exMatch;while((exMatch=exRegex.exec(ev))!==null){const parts=exMatch[1].split(",");for(const p of parts){const exDt=parseIcsDate(p.trim());if(exDt){const exKey=`${exDt.getFullYear()}${String(exDt.getMonth() + 1).padStart(2, "0")}${String(exDt.getDate()).padStart(2, "0")}`;if(!exdates[uid])exdates[uid]=new Set();exdates[uid].add(exKey);}}}
const rruleMatch=ev.match(/RRULE:(.*)/);const recidMatch=ev.match(/RECURRENCE-ID(?:;[^:]+)?:([0-9TZ]+)/);const subject=detectSubject(summary,desc,loc);const meta=extractMetadata(summary,desc,subject);let finalTitle=summary;let finalFaculty=meta.faculty;if(subject==="break"){finalTitle="Lunch Break";finalFaculty="Recess / Lunch";}
const isAllDay=!startMatch[1].includes("T")||(startDt.getHours()===0&&startDt.getMinutes()===0&&endDt.getHours()===0&&endDt.getMinutes()===0&&(endDt.getTime()-startDt.getTime()>=86400000));const eventObj={uid,title:finalTitle,description:desc,cleanDesc:meta.cleanDesc,faculty:finalFaculty,competency:meta.competency,location:loc||"Lt. BRKM Govt. Medical College, Jagdalpur",startDate:startDt,endDate:endDt,startIso:startDt.toISOString(),endIso:endDt.toISOString(),allDay:isAllDay,subject:subject,sessionType:detectSessionType(summary,desc),rawRrule:rruleMatch?rruleMatch[1].trim():null};if(recidMatch){const recDt=parseIcsDate(recidMatch[1].trim());if(recDt){const recKey=`${recDt.getFullYear()}${String(recDt.getMonth() + 1).padStart(2, "0")}${String(recDt.getDate()).padStart(2, "0")}_${String(recDt.getHours()).padStart(2, "0")}${String(recDt.getMinutes()).padStart(2, "0")}`;overrides[`${uid}_${recKey}`]=eventObj;}}else if(rruleMatch){baseRecurring.push(eventObj);}else{standalone.push(eventObj);}}
const now=getNowInKolkata();const windowStart=new Date(now.getTime()-(28*24*60*60*1000));const windowEnd=new Date(now.getTime()+(182*24*60*60*1000));const expandedList=[];for(const ev of standalone){if(ev.startDate>=windowStart&&ev.startDate<windowEnd){expandedList.push(ev);}}
const dayCodeMap={MO:1,TU:2,WE:3,TH:4,FR:5,SA:6,SU:0};for(const rev of baseRecurring){const rule=rev.rawRrule||"";const durationMs=rev.endDate.getTime()-rev.startDate.getTime();const parts={};rule.split(";").forEach((p)=>{const idx=p.indexOf("=");if(idx>0)parts[p.substring(0,idx).trim().toUpperCase()]=p.substring(idx+1).trim();});const freq=parts.FREQ||"WEEKLY";const interval=parseInt(parts.INTERVAL||"1",10)||1;const count=parseInt(parts.COUNT||"999999",10)||999999;let untilDt=null;if(parts.UNTIL){untilDt=parseIcsDate(parts.UNTIL);}
const bydaysRaw=parts.BYDAY||"";const bydays=bydaysRaw.split(",").map((d)=>dayCodeMap[d.trim().substr(0,2).toUpperCase()]).filter((d)=>d!==undefined);let generated=0;const uid=rev.uid;const addInstance=(dtStart)=>{const dKey=`${dtStart.getFullYear()}${String(dtStart.getMonth() + 1).padStart(2, "0")}${String(dtStart.getDate()).padStart(2, "0")}`;const dtKey=`${dKey}_${String(dtStart.getHours()).padStart(2, "0")}${String(dtStart.getMinutes()).padStart(2, "0")}`;if(exdates[uid]&&exdates[uid].has(dKey))return;if(overrides[`${uid}_${dtKey}`]){expandedList.push(overrides[`${uid}_${dtKey}`]);return;}
const inst=Object.assign({},rev);inst.startDate=new Date(dtStart.getTime());inst.endDate=new Date(dtStart.getTime()+durationMs);inst.startIso=inst.startDate.toISOString();inst.endIso=inst.endDate.toISOString();expandedList.push(inst);};if(bydays.length>0&&freq==="WEEKLY"){const dayOfWeek=rev.startDate.getDay();const diffToMonday=(dayOfWeek+6)%7;const startMonday=new Date(rev.startDate.getTime()-(diffToMonday*24*60*60*1000));let curWeek=new Date(startMonday.getTime());while(curWeek<windowEnd&&generated<count){for(let dOffset=0;dOffset<7;dOffset++){const dayDt=new Date(curWeek.getTime()+(dOffset*24*60*60*1000));dayDt.setHours(rev.startDate.getHours(),rev.startDate.getMinutes(),rev.startDate.getSeconds(),0);if(dayDt<rev.startDate)continue;if(untilDt&&dayDt>untilDt)break;if(bydays.includes(dayDt.getDay())){if(dayDt>=windowStart&&dayDt<windowEnd){addInstance(dayDt);}
generated++;if(generated>=count)break;}}
curWeek.setDate(curWeek.getDate()+(7*interval));}}else{let cur=new Date(rev.startDate.getTime());while(cur<windowEnd&&generated<count){if(untilDt&&cur>untilDt)break;if(cur>=windowStart){addInstance(cur);}
generated++;if(freq==="WEEKLY"){cur.setDate(cur.getDate()+(7*interval));}else{cur.setDate(cur.getDate()+interval);}}}}
expandedList.sort((a,b)=>a.startDate.getTime()-b.startDate.getTime());let deduplicated=[];const timeSlotMap=new Map();for(const ev of expandedList){if(ev.title==="🏫 College"&&ev.startDate.getHours()===9&&ev.endDate.getHours()===17){continue;}
const slotKey=`${ev.startDate.toDateString()}_${ev.startDate.getHours()}:${ev.startDate.getMinutes()}_${ev.subject}`;if(timeSlotMap.has(slotKey)){const existing=timeSlotMap.get(slotKey);if((ev.title.includes(":")||ev.title.includes("–"))&&!existing.title.includes(":")){timeSlotMap.set(slotKey,ev);}}else{timeSlotMap.set(slotKey,ev);}}
timeSlotMap.forEach((ev)=>deduplicated.push(ev));const byDateMap=new Map();for(const ev of deduplicated){const dStr=ev.startDate.toDateString();if(!byDateMap.has(dStr))byDateMap.set(dStr,[]);byDateMap.get(dStr).push(ev);}
byDateMap.forEach((dayEvents,dStr)=>{const firstEv=dayEvents[0];const dayOfWeek=firstEv.startDate.getDay();if(dayOfWeek===0)return;const isHoliday=dayEvents.some((e)=>e.subject==="holiday");if(isHoliday)return;const hasClasses=dayEvents.some((e)=>e.subject!=="break");if(!hasClasses)return;const hasLunch=dayEvents.some((e)=>e.startDate.getHours()===13);if(!hasLunch){const d=firstEv.startDate;const lunchStart=new Date(d.getFullYear(),d.getMonth(),d.getDate(),13,0,0);const lunchEnd=new Date(d.getFullYear(),d.getMonth(),d.getDate(),14,0,0);const ymd=`${lunchStart.getFullYear()}-${String(lunchStart.getMonth() + 1).padStart(2, "0")}-${String(lunchStart.getDate()).padStart(2, "0")}`;deduplicated.push({uid:`college_lunch_${ymd}`,title:"Lunch Break",description:"Daily college lunch recess (01:00 PM – 02:00 PM).",cleanDesc:"Daily college lunch recess (01:00 PM – 02:00 PM).",faculty:"Recess / Lunch",competency:"",location:"College Campus / Cafeteria",startDate:lunchStart,endDate:lunchEnd,startIso:lunchStart.toISOString(),endIso:lunchEnd.toISOString(),subject:"break",sessionType:"break",rawRrule:null});}});const holidayDates=new Set(deduplicated.filter((e)=>e.subject==="holiday").map((e)=>e.startDate.toDateString()));deduplicated=deduplicated.filter((e)=>!(holidayDates.has(e.startDate.toDateString())&&e.subject==="break"));deduplicated.sort((a,b)=>a.startDate.getTime()-b.startDate.getTime());return deduplicated;}
async function fetchTimetableData(forceRefresh=false){setLoading(true);state.errorMessage=null;try{const proxyUrl=forceRefresh?"/api/timetable?refresh=1":"/api/timetable";const resp=await fetch(proxyUrl,{cache:forceRefresh?"reload":"default"});if(resp.ok){const icsText=await resp.text();if(icsText&&icsText.includes("BEGIN:VCALENDAR")){const sessions=parseIcalString(icsText);onFetchSuccess(sessions,"proxy");return;}}}catch(_){}
try{const jsonUrl=`assets/data/timetable_college.json?t=${Date.now()}`;const jsonResp=await fetch(jsonUrl);if(jsonResp.ok){const data=await jsonResp.json();if(data&&Array.isArray(data.events)&&data.events.length>0){const parsed=data.events.map((e)=>{const startDt=new Date(e.start.replace(" ","T"));const endDt=new Date(e.end.replace(" ","T"));const sub=e.subject||detectSubject(e.title,e.description,e.location);const meta=extractMetadata(e.title,e.description,sub);const isAllDay=Boolean(e.all_day||(startDt.getHours()===0&&startDt.getMinutes()===0&&endDt.getHours()===0&&endDt.getMinutes()===0&&(endDt.getTime()-startDt.getTime()>=86400000)));return{uid:e.uid,title:e.title,description:e.description,cleanDesc:meta.cleanDesc,faculty:e.faculty||meta.faculty,competency:e.competency||meta.competency,location:e.location||"Lt. BRKM Govt. Medical College, Jagdalpur",startDate:startDt,endDate:endDt,startIso:startDt.toISOString(),endIso:endDt.toISOString(),allDay:isAllDay,subject:sub,sessionType:e.session_type||detectSessionType(e.title,e.description)};});onFetchSuccess(parsed,"pre_synced");return;}}}catch(_){}
try{const corsProxyUrl=`https://api.allorigins.win/raw?url=${encodeURIComponent(PUBLIC_ICAL_URL)}`;const pubResp=await fetch(corsProxyUrl);if(pubResp.ok){const icsText=await pubResp.text();if(icsText&&icsText.includes("BEGIN:VCALENDAR")){const sessions=parseIcalString(icsText);onFetchSuccess(sessions,"cors_public");return;}}}catch(_){}
const cached=loadFromLocalStorage();if(cached&&cached.length>0){onFetchSuccess(cached,"offline_cache");return;}
setLoading(false);showError("Could not load timetable feed. Please check your internet connection or verify the proxy server is running.");}
function onFetchSuccess(sessions,sourceMode){state.allCollegeSessions=sessions;state.lastSyncTime=new Date();state.isSynced=(sourceMode==="proxy"||sourceMode==="college_json"||sourceMode==="direct_ical");setLoading(false);saveToLocalStorage(sessions);updateLastSyncedDisplay();renderAll();}
function saveToLocalStorage(sessions){try{const lightweight=sessions.slice(0,400).map((s)=>({uid:s.uid,title:s.title,description:s.description,cleanDesc:s.cleanDesc,faculty:s.faculty,competency:s.competency,location:s.location,startIso:s.startIso,endIso:s.endIso,subject:s.subject,sessionType:s.sessionType}));localStorage.setItem(CACHE_STORAGE_KEY,JSON.stringify({timestamp:Date.now(),sessions:lightweight}));}catch(_){}}
function loadFromLocalStorage(){try{const raw=localStorage.getItem(CACHE_STORAGE_KEY);if(!raw)return null;const data=JSON.parse(raw);if(data&&Array.isArray(data.sessions)){return data.sessions.map((s)=>({uid:s.uid,title:s.title,description:s.description,cleanDesc:s.cleanDesc,faculty:s.faculty,competency:s.competency,location:s.location,startDate:new Date(s.startIso),endDate:new Date(s.endIso),startIso:s.startIso,endIso:s.endIso,subject:s.subject,sessionType:s.sessionType}));}}catch(_){}
return null;}
function loadSettings(){try{const raw=localStorage.getItem(SETTINGS_STORAGE_KEY);if(raw){const obj=JSON.parse(raw);state.strictCollegeFilter=obj.strictCollegeFilter!==false;state.customIncludeWords=Array.isArray(obj.customIncludeWords)?obj.customIncludeWords:[];state.customExcludeWords=Array.isArray(obj.customExcludeWords)?obj.customExcludeWords:[];state.manualExcludedUids=new Set(Array.isArray(obj.manualExcludedUids)?obj.manualExcludedUids:[]);}}catch(_){}}
function saveSettings(){try{localStorage.setItem(SETTINGS_STORAGE_KEY,JSON.stringify({strictCollegeFilter:state.strictCollegeFilter,customIncludeWords:state.customIncludeWords,customExcludeWords:state.customExcludeWords,manualExcludedUids:Array.from(state.manualExcludedUids)}));}catch(_){}}
function renderAll(){updateCounts();renderHappeningNowBanner();renderTimeline();}
function getFilteredSessions(){let list=state.allCollegeSessions.slice();if(state.selectedSubject!=="all"){list=list.filter((s)=>s.subject===state.selectedSubject);}
if(state.selectedSessionType!=="all"){list=list.filter((s)=>s.sessionType===state.selectedSessionType);}
if(state.searchQuery.trim()){const q=state.searchQuery.toLowerCase().trim();list=list.filter((s)=>{return(s.title.toLowerCase().includes(q)||(s.faculty&&s.faculty.toLowerCase().includes(q))||(s.competency&&s.competency.toLowerCase().includes(q))||(s.location&&s.location.toLowerCase().includes(q))||(s.description&&s.description.toLowerCase().includes(q)));});}
return list;}
function updateCounts(){const now=getNowInKolkata();const todayY=now.getFullYear();const todayM=now.getMonth();const todayD=now.getDate();const todaySessions=state.allCollegeSessions.filter((s)=>{const d=s.startDate;return d.getFullYear()===todayY&&d.getMonth()===todayM&&d.getDate()===todayD;});const todayTeaching=todaySessions.filter((s)=>s.subject!=="break"&&s.subject!=="holiday");if(DOM.tabTodayCount)DOM.tabTodayCount.textContent=todayTeaching.length;const upcomingEnd=new Date(now.getTime()+(14*24*60*60*1000));const upcomingSessions=state.allCollegeSessions.filter((s)=>{return s.startDate>=now&&s.startDate<upcomingEnd;});const upcomingTeaching=upcomingSessions.filter((s)=>s.subject!=="break"&&s.subject!=="holiday");if(DOM.tabUpcomingCount)DOM.tabUpcomingCount.textContent=upcomingTeaching.length;}
function renderHappeningNowBanner(){if(!DOM.nowBannerContainer)return;const now=getNowInKolkata();const activeSession=state.allCollegeSessions.find((s)=>{return now>=s.startDate&&now<s.endDate;});if(!activeSession){const todayNext=state.allCollegeSessions.find((s)=>{const isToday=s.startDate.toDateString()===now.toDateString();return isToday&&s.startDate>now;});if(todayNext){const isAllDay=todayNext.allDay||(todayNext.startDate.getHours()===0&&todayNext.startDate.getMinutes()===0&&todayNext.endDate.getHours()===0&&todayNext.endDate.getMinutes()===0&&(todayNext.endDate.getTime()-todayNext.startDate.getTime()>=86400000));DOM.nowBannerContainer.innerHTML=`
          <div class="now-banner-card">
            <div class="now-banner-top">
              <span class="now-live-tag" style="background: rgba(59, 130, 246, 0.2); border-color: rgba(59, 130, 246, 0.4); color: #93C5FD;">⏳ UP NEXT TODAY</span>
              <span class="now-time-range">${isAllDay ? "ALL DAY" : `${formatTimeAMPM(todayNext.startDate)}– ${formatTimeAMPM(todayNext.endDate)}`}</span>
            </div>
            <h3 class="now-title">${escapeHtml(todayNext.title)}</h3>
            <div class="now-meta-row">
              <span>👨‍🏫 ${escapeHtml(todayNext.faculty || "Department Faculty")}</span>
              ${todayNext.competency ? `<span>📋 Competency:${escapeHtml(todayNext.competency)}</span>` : ""}
            </div>
          </div>
        `;DOM.nowBannerContainer.style.display="block";}else{DOM.nowBannerContainer.innerHTML="";DOM.nowBannerContainer.style.display="none";}
return;}
const totalDuration=activeSession.endDate.getTime()-activeSession.startDate.getTime();const elapsed=now.getTime()-activeSession.startDate.getTime();const percent=Math.min(100,Math.max(0,Math.round((elapsed/totalDuration)*100)));const isActAllDay=activeSession.allDay||(activeSession.startDate.getHours()===0&&activeSession.startDate.getMinutes()===0&&activeSession.endDate.getHours()===0&&activeSession.endDate.getMinutes()===0&&(activeSession.endDate.getTime()-activeSession.startDate.getTime()>=86400000));DOM.nowBannerContainer.innerHTML=`
      <div class="now-banner-card">
        <div class="now-banner-top">
          <span class="now-live-tag">🟢 HAPPENING NOW</span>
          <span class="now-time-range">${isActAllDay ? "ALL DAY" : `${formatTimeAMPM(activeSession.startDate)}– ${formatTimeAMPM(activeSession.endDate)}`}</span>
        </div>
        <h3 class="now-title">${escapeHtml(activeSession.title)}</h3>
        <div class="now-meta-row">
          <span>👨‍🏫 ${escapeHtml(activeSession.faculty || "Department Faculty")}</span>
          ${activeSession.competency ? `<span>📋 Competency:${escapeHtml(activeSession.competency)}</span>` : ""}
        </div>
        <div class="now-progress-track">
          <div class="now-progress-fill" style="width: ${percent}%;"></div>
        </div>
      </div>
    `;DOM.nowBannerContainer.style.display="block";}
function detectImportantSession(s){const text=`${s.title || ""} ${s.description || ""} ${s.cleanDesc || ""}`.toLowerCase();const type=(s.sessionType||"").toLowerCase();if(type==="test_exam"||/\b(pct|exam|examination|assessment|term final|viva|ospe|osce|internal assessment|post-test)\b/i.test(text)){return{type:"exam",label:"Exam / PCT",icon:`<svg width="11" height="11" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2.5"><polygon points="12 2 15.09 8.26 22 9.27 17 14.14 18.18 21.02 12 17.77 5.82 21.02 7 14.14 2 9.27 8.91 8.26 12 2"></polygon></svg>`};}
if(type==="sdl"||/\b(sdl|self-directed learning|self directed learning)\b/i.test(text)){return{type:"sdl",label:"SDL",icon:`<svg width="11" height="11" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2.5"><path d="M2 3h6a4 4 0 0 1 4 4v14a3 3 0 0 0-3-3H2z"></path><path d="M22 3h-6a4 4 0 0 0-4 4v14a3 3 0 0 1 3-3h7z"></path></svg>`};}
if(/\b(special class|guest lecture|integrated seminar|symposium|workshop|foundation course|webinar)\b/i.test(text)){return{type:"special",label:"Special Session",icon:`<svg width="11" height="11" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2.5"><circle cx="12" cy="12" r="10"></circle><polyline points="12 6 12 12 14 14"></polyline></svg>`};}
return null;}
function getDayCategory(groupSessions,dateObj){const holidays=groupSessions.filter((s)=>s.subject==="holiday"||s.sessionType==="holiday");const breaks=groupSessions.filter((s)=>s.subject==="break");const teaching=groupSessions.filter((s)=>s.subject!=="holiday"&&s.sessionType!=="holiday"&&s.subject!=="break");const optional=teaching.filter((s)=>s.subject==="sports"||s.sessionType==="sports"||s.sessionType==="eca"||s.sessionType==="sdl");if(holidays.length>0&&teaching.length===0){return{type:"holiday",label:"Holiday • No Classes",badgeClass:"is-holiday"};}
if(holidays.length>0){const classWord=teaching.length===1?"class":"classes";return{type:"partial-holiday",label:`${teaching.length} ${classWord} • Holiday`,badgeClass:"is-holiday"};}
if(teaching.length===0){const isSun=dateObj&&dateObj.getDay()===0;return{type:"free",label:isSun?"Sunday • Free Day":"Free Day • No Classes",badgeClass:"is-free"};}
if(optional.length===teaching.length&&optional.length>0){const actWord=optional.length===1?"activity":"activities";return{type:"optional-only",label:`Optional Activities (${optional.length} ${actWord})`,badgeClass:"is-optional"};}
const classWord=teaching.length===1?"class":"classes";return{type:"standard",label:`${teaching.length} ${classWord}`,badgeClass:""};}
function renderTimeline(){if(!DOM.timelineContainer)return;const now=getNowInKolkata();const filtered=getFilteredSessions();let sessionsToRender=[];if(state.activeView==="today"){const todayStr=now.toDateString();sessionsToRender=filtered.filter((s)=>s.startDate.toDateString()===todayStr);if(sessionsToRender.length===0){const isSunday=now.getDay()===0;showEmpty(isSunday?"Sunday • College Closed • Rest & Revision Day 🎉":"No college classes scheduled for today.");return;}
hideEmpty();const dayCat=getDayCategory(sessionsToRender,now);let badgeClass="date-divider-badge is-today";if(dayCat.badgeClass&&dayCat.badgeClass!=="is-today"){badgeClass+=" "+dayCat.badgeClass;}
const summaryText=`Today • ${dayCat.label}`;DOM.timelineContainer.innerHTML=`
        <div class="date-divider-header">
          <h2 class="date-divider-title">${formatDateHuman(now)}</h2>
          <span class="${badgeClass}">${summaryText}</span>
        </div>
        ${sessionsToRender.map((s) => createSessionCardHtml(s, now)).join("")}
      `;}else if(state.activeView==="upcoming"){const upcomingEnd=new Date(now.getTime()+(14*24*60*60*1000));sessionsToRender=filtered.filter((s)=>s.startDate>=now&&s.startDate<upcomingEnd);if(sessionsToRender.length===0){showEmpty("No upcoming classes scheduled in the next 14 days.");return;}
hideEmpty();const grouped=new Map();for(const s of sessionsToRender){const dStr=s.startDate.toDateString();if(!grouped.has(dStr))grouped.set(dStr,[]);grouped.get(dStr).push(s);}
let html="";grouped.forEach((groupSessions,dStr)=>{const first=groupSessions[0].startDate;const rel=formatRelativeDay(first,now);const dayCat=getDayCategory(groupSessions,first);let badgeClass="date-divider-badge";if(rel==="Today"){badgeClass+=" is-today";}else if(dayCat.badgeClass){badgeClass+=" "+dayCat.badgeClass;}
const summaryText=rel?`${rel} • ${dayCat.label}`:dayCat.label;html+=`
          <div class="date-divider-header">
            <h2 class="date-divider-title">${formatDateHuman(first)}</h2>
            <span class="${badgeClass}">${summaryText}</span>
          </div>
          ${groupSessions.map((s) => createSessionCardHtml(s, now)).join("")}
        `;});DOM.timelineContainer.innerHTML=html;}
const cards=DOM.timelineContainer.querySelectorAll(".session-card");cards.forEach((card)=>{card.addEventListener("click",()=>{const uid=card.getAttribute("data-session-uid");const startIso=card.getAttribute("data-session-start");const session=state.allCollegeSessions.find((s)=>s.uid===uid&&s.startIso===startIso);if(session)openDetailsModal(session);});});}
function createSessionCardHtml(s,now){const isOngoing=!s.allDay&&now>=s.startDate&&now<s.endDate;const isAllDay=s.allDay||(s.startDate.getHours()===0&&s.startDate.getMinutes()===0&&s.endDate.getHours()===0&&s.endDate.getMinutes()===0&&(s.endDate.getTime()-s.startDate.getTime()>=86400000));const timeFormatted=isAllDay?"ALL DAY":`${formatTimeAMPM(s.startDate)} – ${formatTimeAMPM(s.endDate)}`;const durationMinutes=Math.round((s.endDate.getTime()-s.startDate.getTime())/60000);const durationLabel=isAllDay?"All-Day Event":(durationMinutes>=60?`${Math.floor(durationMinutes / 60)}h ${durationMinutes % 60 ? durationMinutes % 60 + "m" : ""}`:`${durationMinutes}m`);const important=detectImportantSession(s);return`
      <article class="session-card subject-${s.subject} ${isOngoing ? "is-active-session" : ""} ${isAllDay ? "is-allday-card" : ""}" data-session-uid="${escapeHtml(s.uid)}" data-session-start="${escapeHtml(s.startIso)}">
        <div class="session-color-strip"></div>
        <div class="session-card-body">
          <div class="session-card-top">
            <span class="session-time-chip ${isAllDay ? "is-allday-chip" : ""}">
              <svg width="14" height="14" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2.2" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true">
                ${isAllDay ? `<rect x="3"y="4"width="18"height="18"rx="2"ry="2"></rect><line x1="16"y1="2"x2="16"y2="6"></line><line x1="8"y1="2"x2="8"y2="6"></line><line x1="3"y1="10"x2="21"y2="10"></line>` : `<circle cx="12"cy="12"r="10"></circle><polyline points="12 6 12 12 16 14"></polyline>`}
              </svg>
              <span>${timeFormatted}</span> ${!isAllDay ? `<span style="font-weight: 500; color: #94A3B8;">(${durationLabel})</span>` : ""}
            </span>
            <div class="session-badges-group">
              <span class="badge-subject">${escapeHtml(s.subject)}</span>
              <span class="badge-type">${escapeHtml(formatSessionTypeName(s.sessionType))}</span>
              ${important ? `<span class="session-priority-pill priority-${important.type}"title="${important.label}">${important.icon}<span>${important.label}</span></span>` : ""}
              ${isOngoing ? '<span class="now-live-tag" style="padding: 1px 6px; font-size: 0.65rem;">Live</span>' : ""}
            </div>
          </div>
          <h3 class="session-title">${escapeHtml(s.title)}</h3>
          <div class="session-metadata-row">
            ${s.competency ? `<span class="session-competency-pill">${escapeHtml(s.competency)}</span>` : ""}
            <span class="meta-item faculty-item">
              <svg width="13" height="13" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true">
                <path d="M20 21v-2a4 4 0 0 0-4-4H8a4 4 0 0 0-4 4v2"></path>
                <circle cx="12" cy="7" r="4"></circle>
              </svg>
              <span>${escapeHtml(s.faculty || "Department Faculty")}</span>
            </span>
          </div>
        </div>
      </article>
    `;}
function formatSessionTypeName(type){const map={lecture:"Lecture",dissection:"Dissection",practical:"Practical",sgt_doap:"SGT / DOAP",sdl:"SDL",test_exam:"Test / Exam",aetcom:"AETCOM",ece:"ECE",holiday:"Holiday",break:"Break",other:"Session"};return map[type]||"Session";}
function openDetailsModal(s){if(!DOM.detailsModal)return;DOM.detailsTitle.textContent=s.title;const isAllDay=s.allDay||(s.startDate.getHours()===0&&s.startDate.getMinutes()===0&&s.endDate.getHours()===0&&s.endDate.getMinutes()===0&&(s.endDate.getTime()-s.startDate.getTime()>=86400000));DOM.detailsTime.textContent=isAllDay?`${formatDateHuman(s.startDate)} • ALL DAY`:`${formatDateHuman(s.startDate)} • ${formatTimeAMPM(s.startDate)} – ${formatTimeAMPM(s.endDate)}`;DOM.detailsSubjectBadge.textContent=s.subject.toUpperCase();DOM.detailsSubjectBadge.className=`badge-subject subject-${s.subject}`;DOM.detailsTypeBadge.textContent=formatSessionTypeName(s.sessionType);if(s.faculty&&DOM.detailsFaculty){DOM.detailsFaculty.textContent=`Faculty: ${s.faculty}`;DOM.detailsFaculty.style.display="block";}else if(DOM.detailsFaculty){DOM.detailsFaculty.style.display="none";}
if(s.competency&&DOM.detailsCompetency){DOM.detailsCompetency.textContent=`Competency: ${s.competency}`;DOM.detailsCompetency.style.display="block";}else if(DOM.detailsCompetency){DOM.detailsCompetency.style.display="none";}
if(DOM.detailsLocation)DOM.detailsLocation.textContent=s.location;if(DOM.detailsDescription)DOM.detailsDescription.textContent=s.cleanDesc||s.description||"Official college academic session.";if(DOM.detailsExportIcsBtn){DOM.detailsExportIcsBtn.onclick=()=>exportSingleEventIcs(s);}
DOM.detailsModal.classList.add("active");}
function closeDetailsModal(){if(DOM.detailsModal)DOM.detailsModal.classList.remove("active");}
function openSettingsModal(){if(!DOM.settingsModal)return;if(DOM.strictFilterToggle)DOM.strictFilterToggle.checked=state.strictCollegeFilter;if(DOM.customIncludeInput)DOM.customIncludeInput.value=state.customIncludeWords.join(", ");if(DOM.customExcludeInput)DOM.customExcludeInput.value=state.customExcludeWords.join(", ");DOM.settingsModal.classList.add("active");}
function closeSettingsModal(){if(DOM.settingsModal)DOM.settingsModal.classList.remove("active");}
function exportSingleEventIcs(s){const formatIcsDt=(d)=>{return d.getUTCFullYear()+
String(d.getUTCMonth()+1).padStart(2,"0")+
String(d.getUTCDate()).padStart(2,"0")+"T"+
String(d.getUTCHours()).padStart(2,"0")+
String(d.getUTCMinutes()).padStart(2,"0")+
String(d.getUTCSeconds()).padStart(2,"0")+"Z";};const icsContent=["BEGIN:VCALENDAR","VERSION:2.0","PRODID:-//Harsh's Library//MBBS College Timetable//EN","BEGIN:VEVENT",`UID:${s.uid}`,`DTSTAMP:${formatIcsDt(new Date())}`,`DTSTART:${formatIcsDt(s.startDate)}`,`DTEND:${formatIcsDt(s.endDate)}`,`SUMMARY:${s.title.replace(/,/g, "\\,")}`,`DESCRIPTION:${(s.cleanDesc || s.title).replace(/\n/g, "\\n").replace(/,/g, "\\,")}`,`LOCATION:${s.location.replace(/,/g, "\\,")}`,"END:VEVENT","END:VCALENDAR"].join("\r\n");const blob=new Blob([icsContent],{type:"text/calendar;charset=utf-8"});const url=URL.createObjectURL(blob);const a=document.createElement("a");a.href=url;a.download=`${s.title.replace(/[^a-zA-Z0-9_-]/g, "_")}.ics`;document.body.appendChild(a);a.click();document.body.removeChild(a);URL.revokeObjectURL(url);}
function setLoading(loading){state.isLoading=loading;if(DOM.loadingState)DOM.loadingState.style.display=loading?"block":"none";if(DOM.refreshBtn){if(loading)DOM.refreshBtn.classList.add("spinning");else DOM.refreshBtn.classList.remove("spinning");}}
function showEmpty(msg){if(DOM.emptyState){const descEl=DOM.emptyState.querySelector(".timetable-state-desc");if(descEl)descEl.textContent=msg;DOM.emptyState.style.display="block";}
if(DOM.timelineContainer)DOM.timelineContainer.innerHTML="";}
function hideEmpty(){if(DOM.emptyState)DOM.emptyState.style.display="none";}
function showError(msg){if(DOM.errorState){if(DOM.errorDetailsText)DOM.errorDetailsText.textContent=msg;DOM.errorState.style.display="block";}
if(DOM.timelineContainer)DOM.timelineContainer.innerHTML="";}
function hideError(){if(DOM.errorState)DOM.errorState.style.display="none";}
function updateClockDisplay(){if(!DOM.currentTimeBadge)return;const now=getNowInKolkata();DOM.currentTimeBadge.textContent=`${formatTimeAMPM(now)} IST`;}
function updateLastSyncedDisplay(){if(DOM.refreshBtn&&state.lastSyncTime){DOM.refreshBtn.title=`Last synced: ${formatTimeAMPM(state.lastSyncTime)}`;}
if(!DOM.lastSyncedText)return;if(state.isSynced&&state.lastSyncTime){DOM.lastSyncedText.textContent=`Synced: ${formatTimeAMPM(state.lastSyncTime)}`;if(DOM.syncUpToDateBadge)DOM.syncUpToDateBadge.style.display="inline-flex";}else{DOM.lastSyncedText.textContent=state.lastSyncTime?`Cached: ${formatTimeAMPM(state.lastSyncTime)}`:"Syncing...";if(DOM.syncUpToDateBadge)DOM.syncUpToDateBadge.style.display="none";}}
function escapeHtml(str){if(!str)return"";return String(str).replace(/&/g,"&amp;").replace(/</g,"&lt;").replace(/>/g,"&gt;").replace(/"/g,"&quot;").replace(/'/g,"&#039;");}
function setupEventListeners(){if(DOM.refreshBtn){DOM.refreshBtn.addEventListener("click",()=>{fetchTimetableData(true);});}
if(DOM.retryBtn){DOM.retryBtn.addEventListener("click",()=>{hideError();fetchTimetableData(true);});}
if(DOM.filterSettingsBtn){DOM.filterSettingsBtn.addEventListener("click",openSettingsModal);}
if(DOM.settingsCloseBtn){DOM.settingsCloseBtn.addEventListener("click",closeSettingsModal);}
if(DOM.settingsModal){DOM.settingsModal.addEventListener("click",(e)=>{if(e.target===DOM.settingsModal)closeSettingsModal();});}
if(DOM.settingsSaveBtn){DOM.settingsSaveBtn.addEventListener("click",()=>{state.strictCollegeFilter=DOM.strictFilterToggle?DOM.strictFilterToggle.checked:true;state.customIncludeWords=DOM.customIncludeInput?DOM.customIncludeInput.value.split(",").map((s)=>s.trim().toLowerCase()).filter(Boolean):[];state.customExcludeWords=DOM.customExcludeInput?DOM.customExcludeInput.value.split(",").map((s)=>s.trim().toLowerCase()).filter(Boolean):[];saveSettings();closeSettingsModal();fetchTimetableData(false);});}
if(DOM.settingsResetBtn){DOM.settingsResetBtn.addEventListener("click",()=>{state.strictCollegeFilter=true;state.customIncludeWords=[];state.customExcludeWords=[];state.manualExcludedUids.clear();saveSettings();closeSettingsModal();fetchTimetableData(false);});}
if(DOM.viewTabs){DOM.viewTabs.forEach((tab)=>{tab.addEventListener("click",()=>{DOM.viewTabs.forEach((t)=>t.classList.remove("active"));tab.classList.add("active");state.activeView=tab.getAttribute("data-view");renderTimeline();if(DOM.floatingTodayBtn){const shouldShow=(state.activeView==="upcoming"&&window.scrollY>200)||(window.scrollY>400);DOM.floatingTodayBtn.classList.toggle("is-visible",shouldShow);}});});}
if(DOM.floatingTodayBtn){window.addEventListener("scroll",()=>{const shouldShow=(state.activeView==="upcoming"&&window.scrollY>200)||(window.scrollY>400);DOM.floatingTodayBtn.classList.toggle("is-visible",shouldShow);},{passive:true});DOM.floatingTodayBtn.addEventListener("click",()=>{if(state.activeView==="upcoming"){const todayHeader=document.querySelector(".date-divider-header .is-today");if(todayHeader){const target=todayHeader.closest(".date-divider-header")||todayHeader;target.scrollIntoView({behavior:"smooth",block:"start"});return;}}
const todayTab=document.querySelector('.tab-btn[data-view="today"]');if(todayTab){todayTab.click();}
window.scrollTo({top:0,behavior:"smooth"});});}
if(DOM.filterPillsScroll&&DOM.filterPillsContainer){DOM.filterPillsScroll.addEventListener("scroll",()=>{const atEnd=DOM.filterPillsScroll.scrollWidth-DOM.filterPillsScroll.scrollLeft<=DOM.filterPillsScroll.clientWidth+4;DOM.filterPillsContainer.classList.toggle("is-scrolled-end",atEnd);},{passive:true});}
if(DOM.subjectPills){DOM.subjectPills.forEach((pill)=>{pill.addEventListener("click",()=>{DOM.subjectPills.forEach((p)=>p.classList.remove("active"));pill.classList.add("active");state.selectedSubject=pill.getAttribute("data-subject");renderTimeline();});});}
if(DOM.typeSelect){DOM.typeSelect.addEventListener("change",(e)=>{state.selectedSessionType=e.target.value;renderTimeline();});}
if(DOM.searchInput){DOM.searchInput.addEventListener("input",(e)=>{state.searchQuery=e.target.value;if(DOM.searchClear)DOM.searchClear.style.display=state.searchQuery?"block":"none";renderTimeline();});}
if(DOM.searchClear){DOM.searchClear.addEventListener("click",()=>{state.searchQuery="";DOM.searchInput.value="";DOM.searchClear.style.display="none";renderTimeline();});}
if(DOM.detailsCloseBtn){DOM.detailsCloseBtn.addEventListener("click",closeDetailsModal);}
if(DOM.detailsModal){DOM.detailsModal.addEventListener("click",(e)=>{if(e.target===DOM.detailsModal)closeDetailsModal();});}
document.addEventListener("keydown",(e)=>{if(e.key==="Escape"){closeDetailsModal();closeSettingsModal();}});const mobileToggle=document.getElementById("mobile-toggle");const navLinks=document.getElementById("nav-links");if(mobileToggle&&navLinks){mobileToggle.addEventListener("click",()=>{const isShown=navLinks.classList.toggle("show");navLinks.classList.toggle("open",isShown);mobileToggle.setAttribute("aria-expanded",isShown?"true":"false");});navLinks.querySelectorAll(".nav-link").forEach((link)=>{link.addEventListener("click",()=>{navLinks.classList.remove("show");navLinks.classList.remove("open");mobileToggle.setAttribute("aria-expanded","false");});});document.addEventListener("click",(e)=>{if(!mobileToggle.contains(e.target)&&!navLinks.contains(e.target)){if(navLinks.classList.contains("show")||navLinks.classList.contains("open")){navLinks.classList.remove("show");navLinks.classList.remove("open");mobileToggle.setAttribute("aria-expanded","false");}}});}}
function init(){initDOM();loadSettings();setupEventListeners();if(DOM.currentTimeBadge){updateClockDisplay();setInterval(updateClockDisplay,1000);}
setInterval(renderHappeningNowBanner,30000);const cached=loadFromLocalStorage();if(cached&&cached.length>0){onFetchSuccess(cached,"init_cache");}
fetchTimetableData(false);setInterval(()=>{fetchTimetableData(false);},REFRESH_INTERVAL_MS);}
if(document.readyState==="loading"){document.addEventListener("DOMContentLoaded",init);}else{init();}})();